        "agent_id": {
          "type": "string",
          "description": "Filter by agent id or name. A key tied to one agent always reads that agent's mail, and naming another agent is a 403."
        },
        "from": {
          "type": "string",
          "description": "The sender's address contains this text (the display name, which the sender chooses, is not matched)."
        },
        "to": {
          "type": "string",
          "description": "A recipient address contains this text."
        },
        "after": {
          "type": "string",
          "description": "Only mail at or after this time (ISO 8601, or YYYY-MM-DD)."
        },
        "before": {
          "type": "string",
          "description": "Only mail before this time (ISO 8601, or YYYY-MM-DD)."
        },
        "has_attachment": {
          "type": "boolean",
          "description": "`true` for mail with a file attachment, `false` for mail without."
        },
